 {view==='dashboard'&&<><div className="stats-grid">{[[Users,users.filter((u:any)=>u.role==='asesi').length,'Asesi terdaftar','Pada akses Anda'],[ShieldCheck,users.filter((u:any)=>u.role==='asesor').length,'Asesor','Akun asesor'],[Layers3,schemes.length,'Skema okupasi','Dikelola LSP'],[ClipboardCheck,state.docs.filter((d:any)=>d.status==='Diajukan').length,'Menunggu tinjauan','Dokumen diajukan']].map(([Icon,num,title,sub]:any,i)=><div className="stat" key={title}><div className="row between"><span className={'stat-icon c'+i}><Icon size={21}/></span><span className="muted small">{sub}</span></div><strong>{num}</strong><p>{title}</p></div>)}</div><div className="dashboard-grid"><section className="panel"><div className="panel-title"><h2>Alur sertifikasi</h2><button className="text-btn" onClick={()=>navigate('forms')}>Buka dokumen <ArrowUpRight size={15}/></button></div><div className="workflow">{[['01','Permohonan','APL.01 · Data & persyaratan'],['02','Asesmen mandiri','APL.02 · Bukti kompetensi'],['03','Pelaksanaan asesmen','MAPA · IA · Persetujuan'],['04','Rekaman & keputusan','AK · Validasi · Tanda tangan']].map(([n,t,d])=><div key={n}><span>{n}</span><div><strong>{t}</strong><p>{d}</p></div><ChevronRight size={17}/></div>)}</div></section><section className="action-card"><div className="row between"><FileText size={28}/><span>FORMULIR DIGITAL</span></div><h2>{isAdmin?'Siapkan periode asesmen':isAsesi?'Mulai dari data diri':'Tinjau isian asesi'}</h2><p>{isAdmin?'Tambahkan asesi, tentukan skema, lalu tugaskan asesor untuk memulai.':isAsesi?'Lengkapi APL.01, unggah bukti persyaratan, dan lanjutkan asesmen mandiri.':'Lihat dokumen asesi yang ditugaskan kepada Anda dan lengkapi penilaiannya.'}</p><Btn onClick={()=>navigate(isAdmin?'users':'forms')}>{isAdmin?'Kelola asesi':'Buka dokumen'}<ArrowUpRight size={18}/></Btn></section></div><section className="panel"><div className="panel-title"><h2>Skema sertifikasi</h2><button className="text-btn" onClick={()=>navigate('schemes')}>Lihat semua <ChevronRight size={16}/></button></div><div className="scheme-list">{schemes.map((s:any,i:number)=><button key={s.id} onClick={()=>{setSid(s.id);navigate('schemes')}}><span className={'stat-icon c'+i}>{i===0?<Network size={22}/>:i===1?<Calculator size={22}/>:<Monitor size={22}/>}</span><div><strong>{s.name}</strong><p>{s.units.length} unit kompetensi</p></div><Badge>{s.ready?'Aktif':'Belum siap'}</Badge><ChevronRight size={18}/></button>)}</div></section>{isAdmin&&<div className="dashboard-grid"><section className="panel"><div className="panel-title"><h2>Catatan dokumen sumber</h2><AlertCircle size={18} className="amber-text"/></div><p className="muted small source-filename">DOKUMEN MUK - OKUPASI TKJ 2025 2026 Fix(1).docx</p><ul className="notes">{state.notes.map((n:string)=><li key={n}>{n}</li>)}</ul></section><section className="panel"><div className="panel-title"><h2>Aktivitas terbaru</h2><Clock3 size={18}/></div>{state.activity.length?state.activity.slice(0,6).map((a:any)=><div className="activity" key={a.id}><span className="activity-line"/><div><strong>{a.action}</strong><p>{a.actor} · {a.target}</p><small>{fmt(a.created_at)}</small></div></div>):<Empty title="Belum ada aktivitas" description="Aktivitas pengelolaan dan pengisian dokumen akan muncul di sini."/>}</section></div>}</>}
 {view==='users'&&<section className="panel"><div className="toolbar"><div className="row users-filters"><div className="search"><Search size={17}/><input placeholder="Cari nama, username, kelas, atau kelompok…" value={search} onChange={e=>setSearch(e.target.value)}/></div><label className="group-filter"><span>Kelompok</span><Pick value={groupFilter} onChange={setGroupFilter} placeholder="Semua kelompok" options={userGroupOptions}/></label></div><span className="muted">{visibleAsesi.length} dari {asesiUsers.length} asesi</span></div>{isAdmin&&<div className="notice subtle"><ShieldCheck size={18}/>Akun yang dihapus akan diarsipkan, bukan dihapus permanen. Seluruh dokumen asesmen dipertahankan minimal 5 tahun.</div>}<Table><TableHeader><TableRow>{['Nama / username','Peran','Kelas','Kelompok','Skema','Status',''].map((x,i)=><TableHead key={i}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{visibleAsesi.map((u:any)=><TableRow key={u.id}><TableCell><div className="row"><span className="avatar">{u.name.slice(0,2).toUpperCase()}</span><div><strong>{u.name}</strong><small className="block muted">{u.username}</small></div></div></TableCell><TableCell><Badge>{roleName(u.role)}</Badge></TableCell><TableCell>{u.className||'—'}</TableCell><TableCell>{u.groupNumber||'—'}</TableCell><TableCell>{schemes.find((s:any)=>s.id===u.schemeId)?.name||'—'}</TableCell><TableCell><Badge>{u.active?'Aktif':'Nonaktif'}</Badge></TableCell><TableCell>{isAdmin?<div className="row"><button className="text-btn" onClick={()=>{setEdit({...u,password:''});setModal('user')}}>Kelola</button><button className="text-btn danger" onClick={()=>archiveUser(u)}>{u.active?'Hapus':'Pulihkan'}</button></div>:u.role==='asesi'&&<button className="text-btn" onClick={()=>{setSid(u.schemeId);setTarget(u.id);navigate('forms')}}>Lihat isian</button>}</TableCell></TableRow>)}</TableBody></Table>{!visibleAsesi.length&&<Empty title={asesiUsers.length?'Tidak ada asesi pada kelompok ini':'Belum ada asesi'} description={asesiUsers.length?'Ubah kelompok atau kata kunci pencarian untuk melihat asesi lain.':'Akun asesi yang ditugaskan kepada Anda akan tampil di sini.'}/>}</section>}
