 {modal==='reopen'&&<><label>Catatan perbaikan<textarea value={edit.note} onChange={e=>setEdit({...edit,note:e.target.value})}/></label><p className="notice">Tanda tangan sebelumnya akan dibatalkan. Asesi dapat memperbaiki isiannya.</p><Btn disabled={busy} kind="primary" onClick={()=>run(async()=>{const d=await api('reopen',{schemeId:sid,userId:target,code,revision,note:edit.note});setDoc(d.document);setRevision(d.revision);await refresh();setModal('');})}>Buka untuk perbaikan</Btn></>}
